const pedido = $('Disparo autenticado').first().json.body ?? {};
const tentativa = Number(pedido.tentativa ?? 1);
const plataformas = Array.isArray(pedido.plataformas) && pedido.plataformas.length > 0 ? new Set(pedido.plataformas) : null;
const janelasPedidas = Array.isArray(pedido.janelas) ? pedido.janelas : null;
const fontesPedidas = Array.isArray(pedido.fontes) && pedido.fontes.length > 0 ? new Set(pedido.fontes) : null;

const HISTORICO_MESES = { google: 36, meta: 36, ga4: 36, youtube: 36, searchconsole: 16, gbp: 18 };
const MARGEM_DO_LIMITE_DIAS = 7;
const HISTORICO_DIAS = { pixel: 28 };
const PLATAFORMAS_SNAPSHOT = new Set(['gtm', 'rdstation', 'leadads']);
const ATRASO_DIAS = { searchconsole: 3, gbp: 3 };
const MAX_FONTES_POR_PLATAFORMA = { google: 20 };
const DIAS_POR_JANELA = 28;
const DIA_MS = 86_400_000;

const isoDate = (data) => data.toISOString().slice(0, 10);
const [anoLocal, mesLocal, diaLocal] = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()).split('-').map(Number);
const hoje = new Date(Date.UTC(anoLocal, mesLocal - 1, diaLocal));
const meiaNoite = hoje.getTime();

function janelasDaFonte(fonte) {
  if (PLATAFORMAS_SNAPSHOT.has(fonte.platform)) return [fonte.janelaSugerida];

  const meses = HISTORICO_MESES[fonte.platform];
  const dias = HISTORICO_DIAS[fonte.platform];
  if (!meses && !dias) return [];

  const fim = new Date(meiaNoite - (ATRASO_DIAS[fonte.platform] ?? 1) * DIA_MS);
  const limite = dias
    ? new Date(meiaNoite - dias * DIA_MS)
    : new Date(Date.UTC(hoje.getUTCFullYear(), hoje.getUTCMonth() - meses, hoje.getUTCDate() + MARGEM_DO_LIMITE_DIAS));
  const desde = pedido.desde ? new Date(`${pedido.desde}T00:00:00Z`) : null;
  const inicio = desde && desde > limite ? desde : limite;

  const janelas = [];
  let end = fim;
  while (end >= inicio) {
    const startMs = Math.max(end.getTime() - (DIAS_POR_JANELA - 1) * DIA_MS, inicio.getTime());
    janelas.push({ start: isoDate(new Date(startMs)), end: isoDate(end) });
    end = new Date(startMs - DIA_MS);
  }
  return janelas;
}

const saida = [];
const fontesPorPlataforma = new Map();
const ordenadas = $input.all().map((item) => item.json).sort((a, b) => String(a.fonteId).localeCompare(String(b.fonteId)));
for (const fonte of ordenadas) {
  if (plataformas && !plataformas.has(fonte.platform)) continue;
  if (fontesPedidas && !fontesPedidas.has(fonte.fonteId)) continue;
  const teto = MAX_FONTES_POR_PLATAFORMA[fonte.platform];
  const usadas = fontesPorPlataforma.get(fonte.platform) ?? 0;
  if (!janelasPedidas && teto !== undefined && usadas >= teto) continue;
  fontesPorPlataforma.set(fonte.platform, usadas + 1);

  const janelas = janelasPedidas
    ? janelasPedidas.filter((j) => j.fonteId === fonte.fonteId).map((j) => ({ start: j.start, end: j.end }))
    : janelasDaFonte(fonte);

  for (const janela of janelas) saida.push({ json: { fonte, janela, tentativa } });
}

return saida;
